package fr.cercle.tourderole;
import android.app.*;import android.os.*;import android.content.*;import android.content.res.ColorStateList;import android.graphics.*;import android.net.Uri;import android.provider.*;import android.text.*;import android.view.*;import android.widget.*;import android.content.pm.PackageManager;import org.json.*;import java.io.*;import java.util.*;import java.time.*;import java.math.*;import java.util.zip.*;
public class MainActivity extends Activity{
JSONObject cfg,db;JSONArray tabs;String current,query="",filterKey="",filterValue="";LinearLayout root,list;EditText search;int ink=Color.rgb(15,25,31),panel=Color.rgb(29,45,51),paper=Color.rgb(239,235,220),muted=Color.rgb(170,188,188),accent;JSONObject attachment;String attachmentTab;Handler ticker=new Handler();HashMap<String,TextView> timerViews=new HashMap<>();
public void onCreate(Bundle b){super.onCreate(b);try{cfg=new JSONObject(Config.DATA);tabs=cfg.getJSONArray("tabs");accent=Color.parseColor(cfg.getString("color"));db=load(this);for(int i=0;i<tabs.length();i++)if(!db.has(tabs.getJSONObject(i).getString("id")))db.put(tabs.getJSONObject(i).getString("id"),new JSONArray());if(feature().equals("enquetes"))Investigations.seed(this);current=tabs.getJSONObject(0).getString("id");home();ticker.post(tick);}catch(Exception e){error(e);}}
public static JSONObject load(Context c){try{File f=new File(c.getFilesDir(),"records.json");if(!f.exists()&&!new File(f.getPath()+".bak").exists())return new JSONObject();return new JSONObject(new String(read(new android.util.AtomicFile(f).openRead(),6*1024*1024),"UTF-8"));}catch(Exception e){throw new IllegalStateException("Données illisibles : le fichier est préservé.",e);}}
public static synchronized void persist(Context c,JSONObject data)throws Exception{android.util.AtomicFile f=new android.util.AtomicFile(new File(c.getFilesDir(),"records.json"));FileOutputStream out=null;try{out=f.startWrite();out.write(data.toString().getBytes("UTF-8"));f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);throw e;}}
public void save(){try{persist(this,db);}catch(Exception e){error(e);}}public String feature(){return cfg.optString("feature");}public JSONArray rows(String tab){JSONArray a=db.optJSONArray(tab);return a==null?new JSONArray():a;}public JSONObject schema(String id){for(int i=0;i<tabs.length();i++){JSONObject t=tabs.optJSONObject(i);if(t.optString("id").equals(id))return t;}return tabs.optJSONObject(0);}public JSONObject find(String tab,String id){JSONArray a=rows(tab);for(int i=0;i<a.length();i++)if(a.optJSONObject(i).optString("id").equals(id))return a.optJSONObject(i);return null;}public String name(String tab,String id){JSONObject r=find(tab,id);return r==null?"—":r.optString("nom");}
public static byte[] read(InputStream in,int max)throws Exception{try(InputStream input=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=input.read(b))!=-1){if(out.size()+n>max)throw new IOException("Fichier trop volumineux");out.write(b,0,n);}return out.toByteArray();}}
public int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}public TextView text(String s,int size,int col){TextView t=new TextView(this);t.setText(s);t.setTextColor(col);t.setTextSize(size);t.setPadding(dp(8),dp(7),dp(8),dp(7));return t;}public Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(paper);b.setBackgroundTintList(ColorStateList.valueOf(panel));b.setMinHeight(dp(48));b.setOnClickListener(v->{try{action.run();}catch(Exception e){error(e);}});return b;}public LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}public LinearLayout bar(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);return l;}public void addButton(LinearLayout l,String s,Runnable r){l.addView(button(s,r),new LinearLayout.LayoutParams(-1,-2));}public void horizontalButtons(LinearLayout target,Button...buttons){LinearLayout b=bar();for(Button v:buttons)b.addView(v,new LinearLayout.LayoutParams(0,-2,1));target.addView(b);}public void error(Exception e){new AlertDialog.Builder(this).setTitle("Action impossible").setMessage(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage()).setPositiveButton("Fermer",null).show();}public void info(String title,String msg){new AlertDialog.Builder(this).setTitle(title).setMessage(msg).setPositiveButton("Fermer",null).show();}public void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
interface Work{void run()throws Exception;}public void attempt(Work w){try{w.run();}catch(Exception e){error(e);}}
public void frame(String title){root=col();root.setPadding(dp(12),dp(10),dp(12),dp(8));root.setBackgroundColor(ink);setContentView(root);root.addView(text(title,27,paper));timerViews.clear();}
public void home(){frame(cfg.optString("name"));horizontalButtons(root,button("+ Ajouter",()->edit(current,null)),button("Outils",this::tools));HorizontalScrollView hs=new HorizontalScrollView(this);LinearLayout nav=bar();for(int i=0;i<tabs.length();i++){JSONObject t=tabs.optJSONObject(i);String id=t.optString("id");Button b=button(t.optString("title"),()->{current=id;filterKey=filterValue="";query="";home();});if(id.equals(current))b.setTextColor(accent);nav.addView(b);}hs.addView(nav);root.addView(hs);search=new EditText(this);search.setSingleLine(true);search.setTextColor(paper);search.setHintTextColor(muted);search.setHint("Rechercher…");search.setText(query);root.addView(search);if(!filterValue.isEmpty())root.addView(button("Filtre actif · Tout afficher",()->{filterKey=filterValue="";home();}));Domain.actions(this);if(feature().equals("audio"))audioPanel();ScrollView sv=new ScrollView(this);list=col();sv.addView(list);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int n,int a){}public void onTextChanged(CharSequence s,int st,int before,int n){query=s.toString();renderList();}public void afterTextChanged(Editable e){}});renderList();}
public String display(JSONObject row,JSONObject field){String s=row.optString(field.optString("k"));if(field.optString("t").equals("ref"))return name(field.optString("o"),s);if(field.optString("t").equals("bool"))return s.equals("1")?"Oui":"Non";return s;}
public void renderList(){if(list==null)return;list.removeAllViews();ArrayList<JSONObject> all=new ArrayList<>();JSONArray a=rows(current),fields=schema(current).optJSONArray("fields");for(int i=0;i<a.length();i++){JSONObject r=a.optJSONObject(i);if(r==null)continue;if(!filterValue.isEmpty()&&!r.optString(filterKey).equals(filterValue))continue;StringBuilder hay=new StringBuilder();for(int j=0;j<fields.length();j++)hay.append(' ').append(display(r,fields.optJSONObject(j)));if(Core.matches(hay.toString(),query))all.add(r);}if(feature().equals("journal"))Collections.sort(all,(x,y)->y.optString("date").compareTo(x.optString("date")));else Collections.sort(all,(x,y)->Long.compare(y.optLong("modified"),x.optLong("modified")));list.addView(text(all.size()+" élément(s)",13,muted));if(all.isEmpty())list.addView(text(cfg.optString("help")+"\n\nAjoute ton premier élément avec le bouton en haut.",17,muted));if(all.size()>150)list.addView(text("150 premiers résultats affichés : affine la recherche pour les autres.",14,muted));int shown=0;for(JSONObject r:all){if(shown++>=150)break;LinearLayout card=col();card.setPadding(dp(8),dp(6),dp(8),dp(10));card.setBackgroundColor(panel);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(8));list.addView(card,lp);card.addView(text((r.optString("fait").equals("1")?"✓ ":"")+r.optString("nom"),20,paper));StringBuilder sub=new StringBuilder();int n=0;for(int j=1;j<fields.length()&&n<3;j++){JSONObject f=fields.optJSONObject(j);String v=display(r,f);if(!v.isEmpty()){if(sub.length()>0)sub.append(" · ");sub.append(f.optString("l")).append(": ").append(v.length()>100?v.substring(0,100)+"…":v);n++;}}card.addView(text(sub.toString(),14,muted));if(getSharedPreferences("timers",0).getLong(r.optString("id"),0)>0){TextView timer=text(Core.timer(getSharedPreferences("timers",0).getLong(r.optString("id"),0)-System.currentTimeMillis()),26,accent);timerViews.put(r.optString("id"),timer);card.addView(timer);}if(r.has("_file")&&r.optString("_mime").startsWith("image/"))photo(card,r,130);String tab=current;card.setOnClickListener(v->detail(tab,r));card.addView(button("Ouvrir",()->detail(tab,r)));}}
public void photo(LinearLayout parent,JSONObject r,int height){try{File f=file(r.optString("_file"));BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(f.getPath(),o);o.inSampleSize=Math.max(1,Math.max(o.outWidth,o.outHeight)/(height>200?900:300));o.inJustDecodeBounds=false;Bitmap b=BitmapFactory.decodeFile(f.getPath(),o);if(b==null)return;ImageView view=new ImageView(this);view.setImageBitmap(b);view.setAdjustViewBounds(true);view.setScaleType(ImageView.ScaleType.FIT_CENTER);parent.addView(view,new LinearLayout.LayoutParams(-1,dp(height)));}catch(Exception ignored){}}
public void edit(String tab,JSONObject old){JSONObject sch=schema(tab);JSONArray fields=sch.optJSONArray("fields");LinearLayout form=col();form.setPadding(dp(12),0,dp(12),0);HashMap<String,View> inputs=new HashMap<>();HashMap<String,List<String>> refs=new HashMap<>();for(int i=0;i<fields.length();i++){JSONObject f=fields.optJSONObject(i);String k=f.optString("k"),type=f.optString("t"),value=old==null?"":old.optString(k);form.addView(text(f.optString("l")+(type.equals("date")?" · AAAA-MM-JJ":""),15,Color.DKGRAY));View input;if(type.equals("bool")){CheckBox b=new CheckBox(this);b.setChecked(value.equals("1"));input=b;}else if(type.equals("choice")||type.equals("ref")){Spinner sp=new Spinner(this);ArrayList<String> values=new ArrayList<>(),labels=new ArrayList<>();if(type.equals("choice")){JSONArray options=f.optJSONArray("o");for(int j=0;j<options.length();j++){values.add(options.optString(j));labels.add(options.optString(j));}}else{values.add("");labels.add("— Non renseigné —");JSONArray options=rows(f.optString("o"));for(int j=0;j<options.length();j++){JSONObject r=options.optJSONObject(j);values.add(r.optString("id"));labels.add(r.optString("nom"));}}sp.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels));int ix=values.indexOf(value);if(ix>=0)sp.setSelection(ix);refs.put(k,values);input=sp;}else{EditText e=new EditText(this);e.setText(value);e.setTextColor(Color.BLACK);e.setTextSize(17);e.setSingleLine(!type.equals("long"));if(type.equals("long")){e.setMinLines(3);e.setGravity(Gravity.TOP);}if(type.equals("number")||type.equals("money"))e.setInputType(8194);if(type.equals("date")){e.setHint("2026-12-31");e.setOnFocusChangeListener((v,has)->{if(has){Calendar c=Calendar.getInstance();new DatePickerDialog(this,(dp,y,m,d)->e.setText(String.format(Locale.ROOT,"%04d-%02d-%02d",y,m+1,d)),c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();}});}input=e;}inputs.put(k,input);form.addView(input,new LinearLayout.LayoutParams(-1,-2));}ScrollView scroll=new ScrollView(this);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(old==null?"Ajouter":"Modifier").setView(scroll).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->attempt(()->{JSONObject row=old==null?new JSONObject():new JSONObject(old.toString());for(int i=0;i<fields.length();i++){JSONObject f=fields.optJSONObject(i);String k=f.optString("k"),type=f.optString("t"),val="";View in=inputs.get(k);if(in instanceof CheckBox)val=((CheckBox)in).isChecked()?"1":"0";else if(in instanceof Spinner)val=refs.get(k).get(((Spinner)in).getSelectedItemPosition());else val=((EditText)in).getText().toString().trim();if(val.length()>20000)throw new Exception("Texte trop long");if(type.equals("date")&&!Core.date(val))throw new Exception("Date invalide : "+f.optString("l"));if((type.equals("money")||type.equals("number"))&&!val.isEmpty()&&Core.amount(val).signum()<0)throw new Exception("Nombre positif attendu");row.put(k,val);}if(row.optString("nom").isEmpty())throw new Exception("Indique un nom");if(feature().equals("timers"))Core.durations(row.optString("durees"));if(row.has("frequence")&&!row.optString("frequence").isEmpty()&&(Core.intValue(row.optString("frequence"),0)<1||Core.intValue(row.optString("frequence"),0)>3650))throw new Exception("Fréquence : de1à3650jours");if(old==null){row.put("id",UUID.randomUUID().toString());row.put("created",System.currentTimeMillis());rows(tab).put(row);}else{JSONArray a=rows(tab);for(int j=0;j<a.length();j++)if(a.optJSONObject(j).optString("id").equals(old.optString("id")))a.put(j,row);}row.put("modified",System.currentTimeMillis());save();dialog.dismiss();detail(tab,row);})));dialog.show();}
public JSONObject insert(String tab,String name)throws Exception{JSONObject row=new JSONObject();row.put("nom",name);row.put("id",UUID.randomUUID().toString());row.put("created",System.currentTimeMillis());row.put("modified",System.currentTimeMillis());rows(tab).put(row);return row;}
public void detail(String tab,JSONObject r){frame(r.optString("nom"));addButton(root,"← Liste",()->{current=tab;home();});ScrollView scroll=new ScrollView(this);LinearLayout body=col();scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));JSONArray fields=schema(tab).optJSONArray("fields");for(int i=1;i<fields.length();i++){JSONObject f=fields.optJSONObject(i);String v=display(r,f);if(!v.isEmpty())body.addView(text(f.optString("l")+"\n"+v,17,paper));}if(r.optString("_mime").startsWith("image/"))photo(body,r,240);if(r.has("_file")){body.addView(text("Fichier : "+r.optString("_label"),15,muted));addButton(body,"Ouvrir le fichier",()->openFile(r));}Domain.detail(this,body,tab,r);addButton(body,"Modifier",()->edit(tab,r));addButton(body,"Photo / pièce jointe",()->attachMenu(tab,r));if(hasReminder(tab))addButton(body,"Programmer un rappel",()->reminder(tab,r));if(r.optLong("_alarm")>0)addButton(body,"Annuler le rappel",()->{AlarmReceiver.cancel(this,r.optString("id"));r.remove("_alarm");save();detail(tab,r);});if(!r.has("_case"))addButton(body,"Supprimer cet élément",()->new AlertDialog.Builder(this).setTitle("Supprimer « "+r.optString("nom")+" » ?").setMessage("Suppression définitive. Les autres éléments restent conservés.").setNegativeButton("Annuler",null).setPositiveButton("Supprimer",(d,w)->{JSONArray a=rows(tab);for(int i=a.length()-1;i>=0;i--)if(a.optJSONObject(i).optString("id").equals(r.optString("id")))a.remove(i);AlarmReceiver.cancel(this,r.optString("id"));save();current=tab;home();}).show());}
public boolean hasReminder(String tab){JSONArray fields=schema(tab).optJSONArray("fields");for(int i=0;i<fields.length();i++)if(fields.optJSONObject(i).optString("k").equals("echeance"))return true;return false;}
public void reminder(String tab,JSONObject row){attempt(()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},7);Calendar c=Calendar.getInstance();String due=row.optString("echeance");if(!due.isEmpty()){LocalDate date=LocalDate.parse(due);c.set(date.getYear(),date.getMonthValue()-1,date.getDayOfMonth());}new DatePickerDialog(this,(v,y,m,d)->{c.set(y,m,d);new TimePickerDialog(this,(t,h,min)->attempt(()->{c.set(Calendar.HOUR_OF_DAY,h);c.set(Calendar.MINUTE,min);c.set(Calendar.SECOND,0);long when=c.getTimeInMillis();if(when<=System.currentTimeMillis()){toast("Choisis une date future.");return;}row.put("_alarm",when);save();AlarmReceiver.schedule(this,tab,row,when,false);toast("Rappel programmé. Android peut retarder l’alerte en économie d’énergie.");detail(tab,row);}),c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE),true).show();},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();});}

public void attachMenu(String tab,JSONObject row){if(row.has("_file")){new AlertDialog.Builder(this).setTitle("Remplacer la pièce jointe ?").setMessage("Cette version conserve une pièce jointe principale par fiche. Le fichier actuel sera remplacé dans cette fiche. Son original sur ton téléphone reste intact.").setNegativeButton("Annuler",null).setPositiveButton("Continuer",(d,w)->{try{JSONObject metadata=new JSONObject(row.toString());row.remove("_file");attachMenu(tab,row);row.put("_file",metadata.optString("_file"));}catch(Exception e){error(e);}}).show();return;}attachment=row;attachmentTab=tab;new AlertDialog.Builder(this).setTitle("Ajouter un fichier").setItems(new String[]{"Choisir une photo","Prendre une photo","Choisir un document / audio"},(d,i)->{if(i==1){Intent in=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);try{startActivityForResult(in,11);}catch(Exception e){error(e);}}else pick(i==0?"image/*":feature().equals("audio")?"audio/*":"*/*",10,false);}).show();}
public void pick(String mime,int request,boolean multi){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,multi);try{startActivityForResult(i,request);}catch(Exception e){error(e);}}
public File file(String relative)throws Exception{File base=getFilesDir(),f=new File(base,relative);if(relative.isEmpty()||!f.getCanonicalPath().startsWith(base.getCanonicalPath()+File.separator))throw new IOException("Chemin refusé");return f;}
public String label(Uri uri){String name="fichier";try(android.database.Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}catch(Exception ignored){}return Core.safeName(name);}
public String importFile(Uri uri)throws Exception{String name=label(uri);File dir=new File(getFilesDir(),"attachments");dir.mkdirs();String rel="attachments/"+UUID.randomUUID()+"-"+name;File dest=file(rel);try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(dest)){byte[] b=new byte[65536];long total=0;int n;while((n=in.read(b))!=-1){total+=n;if(total>2L*1024*1024*1024)throw new IOException("Limite 2 Go par fichier");out.write(b,0,n);}}catch(Exception e){dest.delete();throw e;}return rel;}
public void busy(String title,Work work){ProgressDialog p=ProgressDialog.show(this,title,"Merci de patienter…",true,false);new Thread(()->{try{work.run();runOnUiThread(()->{p.dismiss();home();});}catch(Exception e){runOnUiThread(()->{p.dismiss();error(e);});}}).start();}
protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null)return;if(request==11){attempt(()->{Bitmap b=(Bitmap)data.getExtras().get("data");if(b==null)throw new Exception("Aucune image reçue");File dir=new File(getFilesDir(),"attachments");dir.mkdirs();String rel="attachments/"+UUID.randomUUID()+".jpg";try(OutputStream out=new FileOutputStream(file(rel))){b.compress(Bitmap.CompressFormat.JPEG,90,out);}attachment.put("_file",rel);attachment.put("_label","Photo");attachment.put("_mime","image/jpeg");save();detail(attachmentTab,attachment);});return;}if(request==10){JSONObject row=attachment;busy("Import du fichier",()->{Uri u=data.getData();String rel=importFile(u);row.put("_file",rel);row.put("_label",label(u));String mime=getContentResolver().getType(u);row.put("_mime",mime==null?"application/octet-stream":mime);persist(this,db);});}if(request==20)busy("Sauvegarde",()->{try(OutputStream out=getContentResolver().openOutputStream(data.getData())){backup(out);}});if(request==21)new AlertDialog.Builder(this).setTitle("Importer la sauvegarde ?").setMessage("Les données actuelles seront remplacées après validation. Exporte-les avant si tu veux les garder.").setNegativeButton("Annuler",null).setPositiveButton("Importer",(d,w)->busy("Import",()->restore(data.getData()))).show();if(request==30){ArrayList<Uri> uris=new ArrayList<>();if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());Documents.merge(this,uris);}}
public void openFile(JSONObject row){attempt(()->{String rel=row.optString("_file"),name=row.optString("_label").toLowerCase(Locale.ROOT);if(feature().equals("audio")){play(row,0);return;}if(name.endsWith(".pdf")||name.endsWith(".epub")||name.endsWith(".cbz")||name.endsWith(".zip")){Reader.open(this,row);return;}Intent in=new Intent(Intent.ACTION_VIEW);in.setDataAndType(FileBridge.uri(this,rel),row.optString("_mime","*/*"));in.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(in);});}
public void tools(){new AlertDialog.Builder(this).setTitle("Outils").setItems(new String[]{"Aide et périmètre","Exporter une sauvegarde ZIP","Importer une sauvegarde ZIP","Exporter cette liste en CSV"},(d,i)->{if(i==0)info(cfg.optString("name"),cfg.optString("help")+"\n\n"+cfg.optString("scope")+"\n\nDonnées locales, sans compte ni publicité. Les sauvegardes ZIP ne sont pas chiffrées. Les notifications peuvent être retardées par Android. La prise de photo utilise la vignette fournie par l’appareil ; importe depuis la galerie pour sa qualité originale. Aucun essai sur téléphone physique effectué pour cette version 0.1.0.");if(i==1){Intent in=new Intent(Intent.ACTION_CREATE_DOCUMENT);in.setType("application/zip");in.addCategory(Intent.CATEGORY_OPENABLE);in.putExtra(Intent.EXTRA_TITLE,cfg.optString("slug")+"-sauvegarde.zip");startActivityForResult(in,20);}if(i==2)pick("application/zip",21,false);if(i==3)csv();}).show();}
public void backup(OutputStream out)throws Exception{try(ZipOutputStream z=new ZipOutputStream(out)){JSONObject envelope=new JSONObject();envelope.put("app",cfg.optString("id"));envelope.put("schema",1);envelope.put("data",db);z.putNextEntry(new ZipEntry("db.json"));z.write(envelope.toString().getBytes("UTF-8"));z.closeEntry();Set<String> files=new HashSet<>();long total=0;for(int t=0;t<tabs.length();t++){JSONArray a=rows(tabs.optJSONObject(t).optString("id"));for(int i=0;i<a.length();i++){String rel=a.optJSONObject(i).optString("_file");if(rel.startsWith("attachments/")&&files.add(rel)&&file(rel).isFile()){File f=file(rel);total+=f.length();if(total>1024L*1024*1024)throw new IOException("Sauvegarde limitée à 1 Go ; conserve les gros médias séparément");z.putNextEntry(new ZipEntry(rel));try(InputStream in=new FileInputStream(f)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)z.write(b,0,n);}z.closeEntry();}}}}}
public void restore(Uri uri)throws Exception{File stage=new File(getCacheDir(),"restore-"+UUID.randomUUID());stage.mkdirs();long total=0;int count=0;try(ZipInputStream z=new ZipInputStream(getContentResolver().openInputStream(uri))){ZipEntry e;while((e=z.getNextEntry())!=null){String n=e.getName();if(++count>1500||e.isDirectory()||(!n.equals("db.json")&&!n.matches("attachments/[\\p{L}\\p{N}._ -]+"))||n.contains(".."))throw new IOException("Archive invalide");File target=new File(stage,n);if(!target.getCanonicalPath().startsWith(stage.getCanonicalPath()+File.separator))throw new IOException("Chemin invalide");target.getParentFile().mkdirs();try(OutputStream o=new FileOutputStream(target)){byte[] b=new byte[65536];int m;while((m=z.read(b))!=-1){total+=m;if(total>1024L*1024*1024)throw new IOException("Archive supérieure à 1 Go");o.write(b,0,m);}}}}File data=new File(stage,"db.json");if(!data.exists())throw new IOException("db.json absent");JSONObject envelope=new JSONObject(new String(read(new FileInputStream(data),6*1024*1024),"UTF-8"));if(!envelope.optString("app").equals(cfg.optString("id"))||envelope.optInt("schema")!=1)throw new IOException("Sauvegarde d’une autre application");JSONObject next=envelope.getJSONObject("data");for(int t=0;t<tabs.length();t++){String id=tabs.optJSONObject(t).optString("id");JSONArray a=next.getJSONArray(id);if(a.length()>10000)throw new IOException("Trop d’éléments");Set<String> ids=new HashSet<>();for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);if(r.optString("id").isEmpty()||!ids.add(r.optString("id"))||r.optString("nom").length()>20000)throw new IOException("Élément invalide");String rel=r.optString("_file");if(!rel.isEmpty()&&(!rel.matches("attachments/[\\p{L}\\p{N}._ -]+")||!new File(stage,rel).isFile()))throw new IOException("Pièce jointe absente");}}File att=new File(stage,"attachments");HashMap<String,String> mapping=new HashMap<>();if(att.isDirectory())for(File f:att.listFiles()){String rel="attachments/"+UUID.randomUUID()+"-"+Core.safeName(f.getName());File dest=file(rel);dest.getParentFile().mkdirs();try(InputStream in=new FileInputStream(f);OutputStream out=new FileOutputStream(dest)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}mapping.put("attachments/"+f.getName(),rel);}for(int ti=0;ti<tabs.length();ti++){JSONArray arr=next.getJSONArray(tabs.optJSONObject(ti).optString("id"));for(int j=0;j<arr.length();j++){JSONObject rr=arr.getJSONObject(j);if(rr.has("_file"))rr.put("_file",mapping.get(rr.optString("_file")));}}for(int t=0;t<tabs.length();t++){JSONArray a=rows(tabs.optJSONObject(t).optString("id"));for(int i=0;i<a.length();i++)AlarmReceiver.cancel(this,a.optJSONObject(i).optString("id"));}persist(this,next);db=next;AlarmReceiver.rebuild(this);runOnUiThread(()->toast("Sauvegarde restaurée."));}
public void csv(){attempt(()->{StringBuilder s=new StringBuilder();JSONArray fields=schema(current).optJSONArray("fields");for(int i=0;i<fields.length();i++)s.append(csvCell(fields.optJSONObject(i).optString("l"))).append(i==fields.length()-1?'\n':';');JSONArray a=rows(current);for(int j=0;j<a.length();j++)for(int i=0;i<fields.length();i++)s.append(csvCell(display(a.optJSONObject(j),fields.optJSONObject(i)))).append(i==fields.length()-1?'\n':';');File dir=new File(getFilesDir(),"exports");dir.mkdirs();String rel="exports/"+current+".csv";try(OutputStream o=new FileOutputStream(file(rel))){o.write(s.toString().getBytes("UTF-8"));}Intent in=new Intent(Intent.ACTION_SEND);in.setType("text/csv");in.putExtra(Intent.EXTRA_STREAM,FileBridge.uri(this,rel));in.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(in,"Exporter la liste"));});}public String csvCell(String s){if(s.startsWith("=")||s.startsWith("+")||s.startsWith("-")||s.startsWith("@"))s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
Runnable tick=new Runnable(){public void run(){try{JSONObject latest=load(MainActivity.this);for(Map.Entry<String,TextView> en:timerViews.entrySet()){JSONArray a=latest.optJSONArray("minuteurs");if(a!=null)for(int i=0;i<a.length();i++){JSONObject r=a.optJSONObject(i);if(r.optString("id").equals(en.getKey()))en.getValue().setText(Core.timer(getSharedPreferences("timers",0).getLong(r.optString("id"),0)-System.currentTimeMillis()));}}if(playerProgress!=null&&AudioService.mp!=null)playerProgress.setText(Core.timer(AudioService.mp.getCurrentPosition())+" / "+Core.timer(AudioService.mp.getDuration()));}catch(Exception ignored){}ticker.postDelayed(this,1000);}};TextView playerProgress;
public void audioPanel(){playerProgress=text("Sélectionne un fichier audio pour commencer.",15,accent);root.addView(playerProgress);horizontalButtons(root,button("−15s",()->AudioService.jump(-15000)),button("Lecture / pause",()->sendAudio("toggle",null,0)),button("+15s",()->AudioService.jump(15000)),button("Arrêter",()->sendAudio("stop",null,0)));SeekBar seek=new SeekBar(this);seek.setMax(1000);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int n,boolean user){if(user&&AudioService.mp!=null)AudioService.seek((int)(AudioService.mp.getDuration()*n/1000L));}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});root.addView(seek);Spinner speed=new Spinner(this);speed.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Vitesse 1×","0,75×","1,25×","1,5×","2×"}));speed.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> a,View v,int i,long id){AudioService.speed(new float[]{1,.75f,1.25f,1.5f,2}[i]);}public void onNothingSelected(AdapterView<?> a){}});root.addView(speed);}
public void sendAudio(String action,JSONObject row,long pos){Intent in=new Intent(this,AudioService.class);in.setAction(action);if(row!=null){in.putExtra("file",row.optString("_file"));in.putExtra("name",row.optString("nom"));in.putExtra("id",row.optString("id"));in.putExtra("position",pos);}if(action.equals("play")&&Build.VERSION.SDK_INT>=26)startForegroundService(in);else startService(in);}public void play(JSONObject row,long pos){if(!row.has("_file")){toast("Ajoute d’abord un fichier audio.");return;}sendAudio("play",row,pos);current="audios";home();}
protected void onPause(){Reader.saveActive(this);ticker.removeCallbacks(tick);super.onPause();}protected void onResume(){super.onResume();if(cfg!=null){ticker.removeCallbacks(tick);ticker.post(tick);}}protected void onDestroy(){Reader.closeActive(this);ticker.removeCallbacksAndMessages(null);super.onDestroy();}public void onBackPressed(){if(!filterValue.isEmpty()){filterKey=filterValue="";home();}else new AlertDialog.Builder(this).setTitle("Revenir à la liste ou fermer ?").setItems(new String[]{"Afficher la liste","Fermer l’application"},(d,i)->{if(i==0)home();else finish();}).show();}
}
